CREATE TABLE OrderLines (
    OrderID INT NOT NULL,
    LineNo SMALLINT NOT NULL,
    Sku VARCHAR(30) NOT NULL,
    Qty INT NOT NULL CONSTRAINT DF_Qty DEFAULT 1,
    Amount AS (Qty * 2) PERSISTED,
    CONSTRAINT PK_OrderLines PRIMARY KEY (OrderID, LineNo)
);
CREATE TABLE Shipments (
    ShipmentID BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    OrderID INT NOT NULL,
    LineNo SMALLINT NOT NULL,
    ShippedAt DATETIMEOFFSET NULL
);
ALTER TABLE Shipments ADD CONSTRAINT FK_Ship_Line FOREIGN KEY (OrderID, LineNo) REFERENCES OrderLines (OrderID, LineNo) ON DELETE NO ACTION ON UPDATE CASCADE;
